import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../models/finance_models.dart';
import '../models/finance_store.dart';
import '../core/theme.dart';
import '../widgets/empty_state.dart';
import 'add_transaction.dart';

class TransactionsScreen extends StatefulWidget { final FinanceStore store; const TransactionsScreen({super.key,required this.store}); @override State<TransactionsScreen> createState()=>_TransactionsScreenState(); }
class _TransactionsScreenState extends State<TransactionsScreen>{ String query=''; TransactionType? filter; FinanceStore get store=>widget.store;
  @override Widget build(BuildContext context){final all=[...store.transactions]..sort((a,b)=>b.date.compareTo(a.date)); final items=all.where((t){final q=query.toLowerCase().trim();final matches=q.isEmpty||t.description.toLowerCase().contains(q)||t.category.toLowerCase().contains(q);return matches&&(filter==null||t.type==filter);}).toList(); final money=NumberFormat.currency(symbol:'\$'); return SafeArea(child:ListView(padding:const EdgeInsets.all(20),children:[Row(children:[Expanded(child:Text('Movimientos',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w800))),IconButton(tooltip:'Nuevo movimiento',onPressed:()=>showTransactionEditor(context,store),icon:const Icon(Icons.add_circle_outline))]),const SizedBox(height:12),const SizedBox(height:8),Align(alignment:Alignment.centerRight,child:OutlinedButton.icon(onPressed:()=>_advancedFilters(context),icon:const Icon(Icons.tune),label:Text((_accountFilter!=null||_categoryFilter!=null||_fromDate!=null||_toDate!=null)?'Filtros activos':'Filtros avanzados'))),TextField(onChanged:(v)=>setState(()=>query=v),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Buscar por descripción o categoría')),const SizedBox(height:10),Wrap(spacing:8,children:[FilterChip(label:const Text('Todos'),selected:filter==null,onSelected:(_)=>setState(()=>filter=null)),FilterChip(label:const Text('Ingresos'),selected:filter==TransactionType.income,onSelected:(_)=>setState(()=>filter=TransactionType.income)),FilterChip(label:const Text('Gastos'),selected:filter==TransactionType.expense,onSelected:(_)=>setState(()=>filter=TransactionType.expense)),FilterChip(label:const Text('Transferencias'),selected:filter==TransactionType.transfer,onSelected:(_)=>setState(()=>filter=TransactionType.transfer))]),const SizedBox(height:16),if(items.isEmpty)EmptyState(icon:Icons.receipt_long_outlined,title:'Sin movimientos todavía',description:'Registra tu primer ingreso, gasto o transferencia para que Finanzia calcule tus saldos y reportes.',actionLabel:'Registrar movimiento',onAction:()=>showTransactionEditor(context,store)),...items.map((t)=>Dismissible(key:ValueKey(t.id),direction:DismissDirection.endToStart,confirmDismiss:(_)=>_confirmDelete(context,t),background:Container(alignment:Alignment.centerRight,padding:const EdgeInsets.all(20),color:FinanziaTheme.coral,child:const Icon(Icons.delete,color:Colors.white)),onDismissed:(_)=>store.deleteTransaction(t.id),child:Card(child:ListTile(onTap:()=>showTransactionEditor(context,store,existing:t),leading:CircleAvatar(child:Icon(t.type==TransactionType.income?Icons.arrow_downward:t.type==TransactionType.expense?Icons.arrow_upward:Icons.swap_horiz)),title:Text(t.description),subtitle:Text('${t.category} · ${DateFormat.yMMMd().format(t.date)}\n${_accountName(t.accountId)}'),isThreeLine:true,trailing:Text('${t.type==TransactionType.income?'+':t.type==TransactionType.expense?'-':''}${money.format(t.amount)}',style:TextStyle(fontWeight:FontWeight.w800,color:t.type==TransactionType.income?FinanziaTheme.green:t.type==TransactionType.expense?FinanziaTheme.coral:null))))))]));}
  String _accountName(String id){for(final a in store.accounts){if(a.id==id)return a.name;}return 'Cuenta eliminada';}
  Future<bool> _confirmDelete(BuildContext context,FinanceTransaction t)async=>await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Eliminar movimiento'),content:Text('¿Eliminar “${t.description}”? Los saldos se recalcularán automáticamente.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Eliminar'))]))??false;
}
